const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newContext({ viewport: { width: 1920, height: 1080 } }).then(c => c.newPage());
  await p.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'domcontentloaded' });
  await p.waitForSelector('.mm-dashboard', { timeout: 20000 });
  await p.waitForTimeout(1000);
  const r = await p.evaluate(() => {
    const appEl = document.querySelector('#app');
    const root = appEl && appEl.__vue__;
    let store = root && root.$store ? root.$store : null;
    // fallback: search vm tree
    if (!store) {
      const dash = document.querySelector('.mm-dashboard');
      const vm = dash && dash.__vue__;
      if (vm && vm.$store) store = vm.$store;
    }
    if (store) {
      store.commit('app/xxx'); // noop ignore
      store.state.app.platformConfig.platformName = '【测试】全局配置平台名';
      return { ok: true };
    }
    return { ok: false, hasApp: !!appEl, hasRoot: !!root };
  });
  console.log('inject:', JSON.stringify(r));
  await p.waitForTimeout(600);
  const t = await p.locator('.mm-dashboard header h1').first().innerText().catch(() => '(none)');
  console.log('title after inject:', JSON.stringify(t));
  await b.close();
})();

