const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newContext({ viewport: { width: 1920, height: 1080 } }).then(c => c.newPage());
  await p.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'domcontentloaded' });
  await p.waitForSelector('.mm-dashboard', { timeout: 20000 });
  await p.waitForTimeout(1000);
  const cb = p.locator('.el-message-box__wrapper .el-button').filter({ hasText: '关闭' }).first();
  if (await cb.count()) await cb.click({ timeout: 3000 }).catch(() => {});

  // default: no sysLogo -> fallback building-2 icon, title static
  const t0 = await p.locator('.mm-dashboard header h1').first().innerText();
  const iconDefault = await p.evaluate(() => {
    const box = document.querySelector('.mm-dashboard header .w-9, .mm-dashboard header .sm\\:w-10');
    const img = box && box.querySelector('img');
    const svg = box && box.querySelector('svg');
    return { hasImg: !!img, hasSvg: !!svg };
  });
  console.log('title(default):', JSON.stringify(t0));
  console.log('icon(default):', JSON.stringify(iconDefault));

  // inject sysLogo (data URL for a simple png) and check img appears
  const dataUrl = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40"><rect width="40" height="40" fill="%23ff6600"/></svg>';
  const r = await p.evaluate((url) => {
    const appEl = document.querySelector('#app');
    const root = appEl && appEl.__vue__;
    const store = root && root.$store;
    if (store) { store.state.app.platformConfig.sysLogo = url; return { ok: true }; }
    return { ok: false };
  }, dataUrl);
  console.log('inject sysLogo:', JSON.stringify(r));
  await p.waitForTimeout(500);
  const iconAfter = await p.evaluate(() => {
    const box = document.querySelector('.mm-dashboard header .w-9, .mm-dashboard header .sm\\:w-10');
    const img = box && box.querySelector('img');
    return { hasImg: !!img, src: img ? img.getAttribute('src').slice(0, 40) : null };
  });
  console.log('icon(after sysLogo):', JSON.stringify(iconAfter));
  const t1 = await p.locator('.mm-dashboard header h1').first().innerText();
  console.log('title(after) still static:', JSON.stringify(t1));
  await b.close();
})();

