  --font-mono: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
}

tool_input.command:
cd 'D:\repository\门户'
$env:NODE_OPTIONS='--max-old-space-size=4096'
npm run build --workspace=zhi2-web-admin 2>&1 | Select-String -Pattern 'error' | Select-Object -Last 3
echo "EXIT: $LASTEXITCODE"
node -e "
const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch();const p=await b.newContext({viewport:{width:1920,height:1080}}).then(c=>c.newPage());
await p.goto('http://127.0.0.1:8092/index.html#/market-monitor',{waitUntil:'domcontentloaded'});await p.waitForSelector('.mm-dashboard',{timeout:20000});await p.waitForTimeout(1200);
const cb=p.locator('.el-message-box__wrapper .el-button').filter({hasText:'关闭'}).first();if(await cb.count())await cb.click({timeout:3000}).catch(()=>{});
const ff=await p.evaluate(()=>{const el=document.querySelector('.mm-dashboard .font-mono')||document.querySelector('.mm-dashboard');return getComputedStyle(el).fontFamily;});
console.log('computed font-family:', ff);
await p.screenshot({path:'.workbuddy/font-final.png',clip:{x:0,y:70,width:1000,height:150}});
await b.close();})();
"
